{"action":"write","path":"sections/07-visit.html","content":"<style>
#visit {font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; color:#1e2a1e; background:#fff8f0; padding:64px 24px;}
#visit h2 {font-size:36px; line-height:1.2; margin:0 0 16px; color:#1a3a2a;}
#visit .visit-wrap {display:grid; grid-template-columns: 1.2fr 0.8fr; gap:32px; align-start;}
#visit address {font-style:normal; background:#fff; border:1px solid #e6d9c8; border-radius:12px; padding:20px; margin:0; line-height:1.6;}
#visit address strong {display:block; font-size:18px; color:#1a3a2a; margin-bottom:4px;}
#visit .hours {background:#fff; border:1px solid #e6d9c8; border-radius:12px; padding:20px;}
#visit .hours h3 {margin:0 0 8px; font-size:18px; color:#1a3a2a;}
#visit .hours ul {list-style:none; margin:0; padding:0;}
#visit .hours li {padding:6px 0;}
#visit .contact {margin-top:12px; font-size:15px;}
#visit .map {display:flex; align-items:center; justify-content:center;}
#visit .map svg {width:100%; height:auto; max-width:320px;}
#visit .map-bg {fill:#e8dcc6;}
#visit .map-pin {fill:#b4532a;}
@media (max-width: 720px) {
  #visit .visit-wrap {grid-template-columns:1fr;}
  #visit h2 {font-size:28px;}
}
</style>
<section id="visit">
  <h2>Visit us</h2>
  <div class="visit-wrap">
    <div>
      <address>
        <strong>Common Ground Coffee</strong>
        42 Willow Street<br>
        Palo Alto, CA
        <span class="contact">hello@commonground.example</span>
      </address>
      <div class="hours">
        <h3>Opening hours</h3>
        <ul>
          <li><strong>Weekdays</strong> 07:00–18:00</li>
          <li><strong>Weekends</strong> 08:00–16:00</li>
        </ul>
        <p>Walk-ins welcome. Training kitchen tours by appointment.</p>
      </div>
    </div>
    <div class="map">
      <svg viewBox="0 0 200 160" aria-hidden="true">
        <rect width="200" height="160" class="map-bg" rx="12"/>
        <path d="M20 120 L180 120" stroke="#c9b48a" stroke-width="4" fill="none"/>
        <circle cx="100" cy="90" r="6" class="map-pin"/>
        <text x="100" y="115" text-anchor="middle" font-size="10" fill="#1a3a2a">42 Willow</text>
      </svg>
    </div>
  </div>
</section>
"}
